def get_correlation(self):
    """
    Calculate correlation
    :return:float
    >>> ds2 = DataStatistics2([1, 2, 3, 4])
    >>> ds2.get_correlation()
    1.0
    """
    import numpy as np
    # If data is 1D, correlate with itself (returns 1.0)
    # If data is 2D, compute correlation matrix between columns
    if self.data.ndim == 1:
        return float(np.var(self.data) > 0)
    elif self.data.ndim == 2:
        corr_matrix = np.corrcoef(self.data)
        return float(corr_matrix[0][1])
    else:
        corr_matrix = np.corrcoef(self.data.T)
        return float(corr_matrix[0][1])

